'use strict';
// Offline renderer for NEBBIA: runs the JavaScript twin of the gen~ code
// (generated by src/build.py) and writes WAV files + basic health checks.
// Usage: node test/render.js [scenarioName ...]
const fs = require('fs');
const path = require('path');

const SR = 48000;
const BLOCK = 64; // gen~ receives parameter changes between signal vectors

function render(sc) {
  const simPath = require.resolve('./nebbia_sim.js');
  delete require.cache[simPath];
  const sim = require(simPath);
  Object.assign(sim.P, { p_bpm: sc.bpm || 120 }, sc.params || {});
  const N = Math.round(sc.seconds * SR);
  const L = new Float32Array(N), R = new Float32Array(N);
  const ev = sc.events.slice().sort((a, b) => a.t - b.t);
  let ei = 0, trig = 0, root = -1, bad = 0;
  const chords = [];
  const bpm = sc.bpm || 120;
  const startBeat = sc.startBeat || 0;
  let lastSt = -1, minLg = 1;
  for (let n = 0; n < N; n++) {
    if (sc.transport) { // emulate plugphasor~ + live.observer is_playing / current_song_time
      const beats = startBeat + n / SR * bpm / 60;
      sim.P.in1 = beats - Math.floor(beats);
      sim.P.p_playing = 1;
      if (n % 2400 === 0) sim.P.p_songbeat = beats;
    }
    if (n % BLOCK === 0) {
      const t = n / SR;
      while (ei < ev.length && ev[ei].t <= t) {
        const e = ev[ei++];
        if (e.type === 'on') {
          sim.P.p_root = e.note; sim.P.p_vel = e.vel || 100; sim.P.p_gate = 1;
          trig = (trig % 9999) + 1; sim.P.p_trig = trig; root = e.note;

        } else if (e.type === 'off') {
          if (e.note === root) sim.P.p_gate = 0;
        } else if (e.type === 'param') {
          sim.P[e.name] = e.value;
        }
      }
    }
    sim.perform();
    if ((n & 15) === 0) minLg = Math.min(minLg, sim.peek('h_lg'));
    const st = sim.peek('h_st');
    if (st === 0 && lastSt !== 0) chords.push({ t: n / SR, note: sim.peek('h_rootin'), at: n + BLOCK * 2 });
    lastSt = st;
    const o = sim.out;
    if (!Number.isFinite(o[0]) || !Number.isFinite(o[1])) bad++;
    L[n] = o[0]; R[n] = o[1];
    for (const c of chords) {
      if (c.at === n) {
        const nn = sim.peek('h_nn');
        c.notes = [];
        for (let s = 0; s < nn; s++) c.notes.push(sim.peek('h_q' + s));
      }
    }
  }
  return { L, R, bad, chords, minLg };
}

function writeWav(file, L, R) {
  const N = L.length, buf = Buffer.alloc(44 + N * 4);
  buf.write('RIFF', 0); buf.writeUInt32LE(36 + N * 4, 4); buf.write('WAVE', 8);
  buf.write('fmt ', 12); buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(2, 22);
  buf.writeUInt32LE(SR, 24); buf.writeUInt32LE(SR * 4, 28); buf.writeUInt16LE(4, 32); buf.writeUInt16LE(16, 34);
  buf.write('data', 36); buf.writeUInt32LE(N * 4, 40);
  for (let i = 0; i < N; i++) {
    const l = Math.max(-1, Math.min(1, L[i])), r = Math.max(-1, Math.min(1, R[i]));
    buf.writeInt16LE(Math.round(l * 32767), 44 + i * 4);
    buf.writeInt16LE(Math.round(r * 32767), 46 + i * 4);
  }
  fs.writeFileSync(file, buf);
}

const NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const nn = (m) => NAMES[((Math.round(m) % 12) + 12) % 12] + (Math.floor(Math.round(m) / 12) - 1);

function stats(name, r) {
  const { L, R } = r;
  let peak = 0, dc = 0;
  const secs = [];
  for (let s = 0; s < L.length; s += SR) {
    let acc = 0, e = Math.min(L.length, s + SR);
    for (let i = s; i < e; i++) { acc += L[i] * L[i] + R[i] * R[i]; }
    secs.push(10 * Math.log10(acc / (2 * (e - s)) + 1e-20));
  }
  for (let i = 0; i < L.length; i++) { peak = Math.max(peak, Math.abs(L[i]), Math.abs(R[i])); dc += L[i] + R[i]; }
  let corr = 0, el = 0, er = 0;
  for (let i = 0; i < L.length; i++) { corr += L[i] * R[i]; el += L[i] * L[i]; er += R[i] * R[i]; }
  console.log(`\n[${name}] peak ${(20 * Math.log10(peak + 1e-20)).toFixed(1)} dBFS, non-finite samples ${r.bad}, ` +
    `DC ${(dc / (2 * L.length)).toExponential(1)}, L/R correlation ${(corr / Math.sqrt(el * er + 1e-30)).toFixed(2)}, ` +
    `limiter ${(20 * Math.log10(r.minLg)).toFixed(1)} dB`);
  console.log('  RMS per second (dB): ' + secs.map((x) => x.toFixed(0)).join(' '));
  if (r.chords.length) {
    console.log('  chords: ' + r.chords.slice(0, 12).map((c) => c.t.toFixed(3) + 's ' + nn(c.note) + '→[' +
      (c.notes || []).map(nn).join(' ') + ']').join('  '));
  }
}

// ---------------------------------------------------------------- scenarios
const beat = 0.5; // 120 BPM
function stabs(roots, opts = {}) {
  const ev = [];
  const len = opts.len || 0.11;
  roots.forEach((rt, bar) => {
    for (let b = 0; b < 4; b++) {
      const t = bar * 4 * beat + b * beat + beat / 2; // off-beat stabs
      const vel = 85 + ((b * 37 + bar * 11) % 30);
      ev.push({ t, type: 'on', note: rt, vel }, { t: t + len, type: 'off', note: rt });
    }
  });
  return ev;
}

const SCENARIOS = {
  // default patch: parallel minor-9 dub stabs, Am9 Am9 Fm9 Gm9
  dub_stabs: { seconds: 15, events: stabs([57, 57, 53, 55]) },
  // in-key mode: D dorian, the chord brain voice-leads a progression, glide + strum, pad envelope
  dorian_pads: {
    seconds: 17,
    params: { p_harm: 2, p_key: 2, p_notes: 4, p_voicing: 6, p_glide: 220, p_strum: 45, p_aa: 500, p_ad: 2500,
      p_as: 65, p_ar: 2500, p_fa: 900, p_fd: 3000, p_fs: 40, p_cutoff: 700, p_fenv: 25, p_emix: 30,
      p_tune: 75, p_rmix: 40, p_rdecay: 7000, p_etime: 5 },
    events: [[50, 0], [53, 2.5], [55, 5], [57, 7.5], [48, 10]].flatMap(([n, t]) =>
      [{ t, type: 'on', note: n, vel: 90 }, { t: t + 2.3, type: 'off', note: n }]),
  },
  // everything at the limits: must stay finite and bounded
  torture: {
    seconds: 12,
    params: { p_reso: 100, p_drive: 100, p_efb: 110, p_edrive: 100, p_tune: 100, p_rdecay: 20000, p_sdecay: 20000,
      p_rmix: 100, p_emix: 100, p_cutoff: 16000, p_fenv: 100, p_sag: 100, p_age: 100, p_drift: 100,
      p_notes: 6, p_chord: 2, p_sub: 100, p_air: 100, p_vol: 6, p_diff: 100, p_rsize: 150, p_rmod: 100,
      p_glide: 2000, p_strum: -250 },
    events: stabs([36, 84, 60], { len: 0.4 }).concat([
      { t: 3, type: 'param', name: 'p_cutoff', value: 30 }, { t: 4, type: 'param', name: 'p_etime', value: 0 },
      { t: 5, type: 'param', name: 'p_slope', value: 1 }, { t: 6, type: 'param', name: 'p_lfowave', value: 2 },
      { t: 6, type: 'param', name: 'p_lfoamt', value: 100 }, { t: 6, type: 'param', name: 'p_lforate', value: 12 },
    ]),
  },
};

// isolated space test: one Am9 stab, no echo, tail analysed by test/analyse_space.py
for (const tune of [0, 100]) {
  SCENARIOS['space_tune' + tune] = {
    seconds: 5, params: { p_emix: 0, p_rmix: 100, p_tune: tune, p_rdecay: 6000, p_sdecay: 6000 },
    events: [{ t: 0.05, type: 'on', note: 57, vel: 110 }, { t: 0.2, type: 'off', note: 57 }],
  };
}

// internal 4-step sequencer, default pattern (1/4 + 50% offset = off-beat stabs), Live playing at 120 BPM
SCENARIOS.seq_play = { seconds: 6, transport: true, params: { p_seqon: 1, p_seqmode: 0 }, events: [] };
// progression: one chord per bar, D dorian, steps D F G A
SCENARIOS.seq_bars = {
  seconds: 10, transport: true, events: [],
  params: { p_seqon: 1, p_seqmode: 0, p_seqrate: 4, p_seqlen: 4, p_sgate: 90, p_son1: 1, p_son2: 1, p_son3: 1,
    p_son4: 1, p_son5: 0, p_son6: 0, p_son7: 0, p_son8: 0, p_harm: 2, p_key: 2, p_snote1: 0, p_snote2: 3, p_snote3: 5,
    p_snote4: 7, p_as: 60, p_ad: 1500, p_glide: 150 },
};
// transpose mode: hold D3 from beat 2 to beat 6 -> pattern transposed by +2, silent otherwise
SCENARIOS.seq_trans = {
  seconds: 4, transport: true, params: { p_seqon: 1, p_seqmode: 1 },
  events: [{ t: 1.0, type: 'on', note: 62, vel: 100 }, { t: 3.0, type: 'off', note: 62 }],
};
// chord dice at 100 %: every stab rolls colour + voicing
SCENARIOS.dice = { seconds: 9, params: { p_cchance: 100, p_cdice: 2 }, events: stabs([57, 57]) };

// steps 1, 3, 6, 8 on with +0, +3, +5, -2 semitones from the Key (A): A, C, D, G; accent on step 6
SCENARIOS.seq_pos = {
  seconds: 2.1, transport: true, events: [],
  params: { p_seqon: 1, p_son1: 1, p_son2: 0, p_son3: 1, p_son4: 0, p_son5: 0, p_son6: 1, p_son7: 0, p_son8: 1,
    p_snote1: 0, p_snote3: 3, p_snote6: 5, p_snote8: -2, p_sacc6: 1, p_chordon: 0 },
};
// every section switched off: single notes, no filter, no echo, no space, no chorus, no analog
SCENARIOS.all_off = {
  seconds: 4, events: stabs([57]),
  params: { p_chordon: 0, p_filton: 0, p_echoon: 0, p_spaceon: 0, p_choron: 0, p_analogon: 0 },
};
// echo switched off while it is ringing: the tail must fade out quickly
SCENARIOS.echo_kill = {
  seconds: 4, events: stabs([57]).concat([{ t: 2.0, type: 'param', name: 'p_echoon', value: 0 }]),
  params: { p_spaceon: 0, p_efb: 90 },
};

// external scenarios (used by test/random_tour.py)
if (process.env.NEBBIA_SCENARIOS) {
  for (const k of Object.keys(SCENARIOS)) delete SCENARIOS[k];
  Object.assign(SCENARIOS, JSON.parse(fs.readFileSync(process.env.NEBBIA_SCENARIOS, 'utf8')));
}

// internal reverb off, strings on: the tail must still sing the chord
SCENARIOS.space_rev_off = {
  seconds: 5, params: { p_emix: 0, p_rmix: 100, p_tune: 100, p_rdecay: 6000, p_sdecay: 6000, p_reverbon: 0 },
  events: [{ t: 0.05, type: 'on', note: 57, vel: 110 }, { t: 0.2, type: 'off', note: 57 }],
};

const want = process.argv.slice(2);
const outDir = path.join(__dirname, '..', 'demo');
fs.mkdirSync(outDir, { recursive: true });
for (const [name, sc] of Object.entries(SCENARIOS)) {
  if (want.length && !want.includes(name)) continue;
  const t0 = Date.now();
  const r = render(sc);
  stats(name, r);
  console.log(`  rendered ${sc.seconds}s in ${((Date.now() - t0) / 1000).toFixed(1)}s`);
  writeWav(path.join(outDir, name + '.wav'), r.L, r.R);
}
